// Check status is 200
pm.test("Status is 200 - device found", () => {
  pm.response.to.have.status(200);
});

// Check response time (like your 3 sec Titan API SLA)
pm.test("Response within 3000ms", () => {
  pm.expect(pm.response.responseTime).to.be.below(3000);
});

// Check device data fields exist in response
pm.test("Device data fields are present", () => {
  const data = pm.response.json().data;
  pm.expect(data.id).to.exist;
  pm.expect(data.email).to.exist;
  pm.expect(data.first_name).to.be.a("string");
});

// Invalid device should return 404 not 200
pm.test("Status is 404 - device not found", () => {
  pm.response.to.have.status(404);
});

// Response body should be empty — no data returned
pm.test("No device data returned for invalid ID", () => {
  const body = pm.response.json();
  pm.expect(Object.keys(body).length).to.eql(0);
});

// Validate exact ID value returned
pm.test("Device ID matches requested ID", () => {
  const data = pm.response.json().data;
  pm.expect(data.id).to.eql(1);
});

// Validate email format contains @ symbol
pm.test("Email field is valid format", () => {
  const data = pm.response.json().data;
  pm.expect(data.email).to.include("@");
});

// Validate avatar URL field is a string
pm.test("Avatar field is a string URL", () => {
  const data = pm.response.json().data;
  pm.expect(data.avatar).to.be.a("string");
});
